SELECT title, count(*) FROM (SELECT * FROM streamed_table('/pgch_2023104_1_1_0', 'title String, eventdate Date, counterid Int32, isrefresh Int16, dontcounthits Int16')) WHERE ((eventdate >= '2013-07-01')) AND ((eventdate <= '2013-07-31')) AND ((title <> '')) AND ((counterid = 62)) AND ((dontcounthits = 0)) AND ((isrefresh = 0)) GROUP BY title ORDER BY count(*) DESC NULLS FIRST LIMIT 10
